{
  "steps": [
    {
      "id": "s1",
      "desc": "Create a new nullable column country_code VARCHAR(2) on the users table without a default value to avoid locking the large table.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Deploy the application code to implement dual-writes, sending the country_code to the database on every signup and profile update.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "desc": "Deploy the application code to read country_code from the database with a fallback to the geolocation service for legacy null rows.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Run a batch backfill job to populate country_code for existing 50 million rows using the geolocation service, processing in small chunks to minimize load.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Execute verification queries to ensure all rows have a populated country_code and that the dual-write mechanism is functioning correctly.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Add a CHECK constraint on country_code to enforce the ISO-3166 alpha-2 format (^[A-Z]{2}$) on the non-null data.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Alter the column to NOT NULL, which is safe because the previous steps ensured no nulls exist and the check constraint is active.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Update the application code to remove the dual-write logic and fallback handling, relying solely on the database column.",
      "deps": [
        "s7"
      ]
    },
    {
      "id": "s9",
      "desc": "Run integration tests to verify that new signups and profile updates correctly populate and validate the country_code without fallbacks.",
      "deps": [
        "s8"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Author the database migration script to add the new nullable primary_email column to the accounts table.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Deploy the database migration to all database instances to create the new column without affecting existing data.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "desc": "Deploy application version R1 that implements dual-write logic to write to both the old email and new primary_email columns on every update.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Deploy application version R2 that updates all read paths to use COALESCE(primary_email, email) to prefer the new column while falling back to the old one.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Run the backfill job to copy existing data from the email column to the primary_email column for all historical records.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Verify data consistency by auditing a sample of records to ensure primary_email matches email and that no writes have failed.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Deploy application version R3 that removes the dual-write logic and writes exclusively to the primary_email column.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Update the database schema migration to drop the old email column after confirming all application replicas are running R3.",
      "deps": [
        "s7"
      ]
    },
    {
      "id": "s9",
      "desc": "Execute the final database migration to remove the deprecated email column from the accounts table.",
      "deps": [
        "s8"
      ]
    },
    {
      "id": "s10",
      "desc": "Run integration tests to validate that the system functions correctly using only the primary_email column end-to-end.",
      "deps": [
        "s9"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Identify the 4,000 orphan rows in the orders table by performing a LEFT JOIN with customers where customers.id IS NULL.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Implement an application-layer guard or trigger to prevent the insertion of new orders with non-existent customer IDs during the migration window.",
      "deps": []
    },
    {
      "id": "s3",
      "desc": "Define and execute a cleanup policy to either delete or reassign the identified orphan rows to a default 'Unknown' customer account.",
      "deps": [
        "s1",
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Verify that zero orphan rows remain in the orders table after the cleanup execution.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Add the foreign key constraint from orders.customer_id to customers.id with ON DELETE RESTRICT using the NOT VALID option to avoid locking the table.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Validate the newly added foreign key constraint to backfill checks for existing rows without holding an exclusive lock on the orders table.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Run integration tests to confirm that inserting valid orders succeeds while inserting orders with invalid customer IDs fails.",
      "deps": [
        "s6"
      ]
    }
  ]
}

{
  "steps": [
    {
      "id": "s1",
      "desc": "Capture baseline performance metrics and EXPLAIN plans for the unprocessed-events query to establish a pre-change reference point.",
      "deps": []
    },
    {
      "id": "s2",
      "desc": "Execute CREATE INDEX CONCURRENTLY on the events table for the new partial index on created_at where processed_at IS NULL.",
      "deps": [
        "s1"
      ]
    },
    {
      "id": "s3",
      "desc": "Monitor the index creation process for invalid states and trigger a manual REINDEX CONCURRENTLY if the index becomes invalid due to interruption.",
      "deps": [
        "s2"
      ]
    },
    {
      "id": "s4",
      "desc": "Run ANALYZE on the events table to update planner statistics and ensure the new index is visible to the query optimizer.",
      "deps": [
        "s3"
      ]
    },
    {
      "id": "s5",
      "desc": "Verify that the query planner has adopted the new partial index by checking EXPLAIN ANALYZE output for the target workload.",
      "deps": [
        "s4"
      ]
    },
    {
      "id": "s6",
      "desc": "Enter a bake period of at least 24 hours to monitor query latency and throughput stability with the new index active.",
      "deps": [
        "s5"
      ]
    },
    {
      "id": "s7",
      "desc": "Execute DROP INDEX CONCURRENTLY on the old idx_events_created_at index to free up storage and reduce write overhead.",
      "deps": [
        "s6"
      ]
    },
    {
      "id": "s8",
      "desc": "Update the operational runbook to document the new index schema, monitoring thresholds, and rollback procedures.",
      "deps": [
        "s7"
      ]
    }
  ]
}
